    // Extract surrounding context
    const start = Math.max(0, idx - 80);
    const end = Math.min(buf.length, idx + 80);
    const context = buf.slice(start, end).toString('latin1').replace(/[^\x20-\x7e]/g, ' ');
    mouseIdx.push({pos: idx, context});
    idx++;
}
console.log('\nFound', mouseIdx.length, 'occurrences of \"mouse\":');
mouseIdx.forEach(m => console.log('  @' + m.pos + ':', m.context));
